from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        # all equal digits (edge case)
        d = draw(st.sampled_from('123456789'))
        s = d * n
    elif mode == 1:
        # all nines (maximum digit value)
        s = '9' * n
    elif mode == 2:
        # sorted ascending digits
        s = ''.join(sorted(draw(st.text(alphabet='123456789', min_size=n, max_size=n))))
    else:
        s = draw(st.text(alphabet='123456789', min_size=n, max_size=n))
    return f"{n}\n{s}\n"

def validate(inp):
    t = inp.split()
    if len(t) != 2:
        return False
    if not t[0].isdigit():
        return False
    n = int(t[0])
    s = t[1]
    if not (1 <= n <= 2 * 10**5):
        return False
    if len(s) != n:
        return False
    return all(c in '123456789' for c in s)

def ref(inp):
    t = inp.split()
    n = int(t[0])
    s = t[1]
    total = 0
    for i in range(n):
        for j in range(i, n):
            total += int(s[i:j + 1])
    return str(total)
